import React, { useState } from 'react';
import { MdArrowRight } from "react-icons/md";
import { FaShareSquare } from "react-icons/fa";
import { addToCart } from '../../../slices/cartSlice';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { loadStripe } from '@stripe/stripe-js';
import toast from 'react-hot-toast';

// Initialize Stripe with your publishable key
const stripePromise = loadStripe("pk_test_51QgUBjAEDU2aKHD90SHrTkm1VMJWtOzlApsWd9K3PAFOhSSUAyUHX5K09HNcf1GBJG4XH8DUygTVODUR4p0MNGzn00xbXYGQFW");

const CourseBuyCard = ({ course, setConfirmationModal }) => {
  const { token } = useSelector((state) => state.auth);
  const { user } = useSelector((state) => state.profile);
  const { cart } = useSelector((state) => state.cart);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);

  const handleBuyCourse = async () => {
    if (!token || user?.accountType !== 'Student') {
      setConfirmationModal(true);
      return;
    }

    setIsLoading(true);
    try {
      const stripe = await stripePromise;

      if (!stripe) {
        throw new Error("Stripe failed to initialize");
      }

      // Create checkout session
      const response = await fetch("http://localhost:4000/api/v1/payment/create-checkout-session", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify({
          products: [course],
          userId: user._id
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to create checkout session');
      }

      const { id: sessionId } = await response.json();

      if (!sessionId) {
        throw new Error('Invalid session ID received');
      }

      // Redirect to Stripe checkout
      const { error } = await stripe.redirectToCheckout({
        sessionId
      });

      if (error) {
        throw new Error(error.message);
      }
    } catch (error) {
      console.error("Payment error:", error);
      toast.error(error.message || "Payment failed. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    toast.success('Link copied to your clipboard');
  };

  const addToCartHandler = () => {
    if (user?.accountType === 'Student') {
      dispatch(addToCart(course));
      toast.success("Course added to cart");
    } else {
      toast.error("Only students are allowed to buy courses");
    }
  };

  const isEnrolled = user && course?.studentsEnrolled?.includes(user?._id);
  const isInCart = cart?.find((courseInCart) => courseInCart?._id === course?._id);

  return (
    <div className='text-white flex flex-col gap-2'>
      <div className='flex flex-col gap-2'>
        <img 
          src={course?.thumbnail} 
          alt={course?.courseName || 'Course thumbnail'} 
          className='rounded-lg w-full object-cover'
        />
        <h1 className='self-start text-2xl font-bold'>
          {course?.price ? `Rs. ${course.price}` : 'Free'}
        </h1>
      </div>

      <div className='flex flex-col gap-3'>
        <button 
          className={`bg-yellow-50 w-full text-black py-2 px-4 rounded-md hover:bg-yellow-100 transition-colors ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
          onClick={isEnrolled ? () => navigate('/dashboard/enrolled-courses') : handleBuyCourse}
          disabled={isLoading}
        >
          {isLoading ? 'Processing...' : isEnrolled ? 'Go to Course' : 'Buy Now'}
        </button>

        {!isEnrolled && (
          isInCart ? (
            <button 
              onClick={() => navigate('/dashboard/cart')} 
              className='bg-richblack-800 rounded-md w-full px-3 py-2 hover:bg-richblack-700 transition-colors'
            >
              View in Cart
            </button>
          ) : (
            <button 
              onClick={addToCartHandler} 
              className='bg-richblack-800 rounded-md w-full px-3 py-2 hover:bg-richblack-700 transition-colors'
            >
              Add to Cart
            </button>
          )
        )}
      </div>

      <p className='self-center text-richblack-300 text-sm'>30 Days Money Back Guarantee</p>

      <div className='mt-4'>
        <h2 className='text-lg font-semibold mb-2'>This Course Includes:</h2>
        <ul className='text-caribbeangreen-200 flex flex-col gap-2'>
          <li className='flex gap-1 items-center'>
            <MdArrowRight className="text-lg" />
            <span>8 hours of lectures</span>
          </li>
          <li className='flex gap-1 items-center'>
            <MdArrowRight className="text-lg" />
            <span>End to end projects</span>
          </li>
        </ul>
      </div>

      <button 
        className='mt-6 flex gap-2 items-center text-yellow-100 justify-center hover:text-yellow-200 transition-colors' 
        onClick={handleShare}
      >
        <FaShareSquare />
        <span>Share</span>
      </button>
    </div>
  );
};

export default CourseBuyCard;
